(()=>{
'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const fmt=(v,d=2)=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const today=()=>new Date().toISOString().slice(0,10);
const S={token:localStorage.erp_token||'',me:null,systemInfo:null,settings:{},companies:[],users:[],companyId:localStorage.erp_company||'',accounts:[],groupAccounts:[],parties:[],banks:[],currencies:[],assetCategories:[],assets:[],page:'dashboard',chartTab:'group',modalSubmit:null,lastReportTitle:'',lastReportHtml:''};

function toast(message,error=false){const t=$('toast');t.textContent=message;t.className='toast'+(error?' error':'');t.classList.remove('hidden');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.add('hidden'),4200)}
async function api(path,opt={}){const headers={'Content-Type':'application/json',...(opt.headers||{})};if(S.token)headers.Authorization=`Bearer ${S.token}`;let r;try{r=await fetch(path,{...opt,headers})}catch{throw Error('تعذر الاتصال بالخادم. تأكد أن خدمة Render بحالة Live.')}const raw=await r.text();let data=null;if(raw){try{data=JSON.parse(raw)}catch{data={detail:raw}}}if(r.status===401){logout(false);throw Error(data?.detail||'انتهت الجلسة أو بيانات الدخول غير صحيحة')}if(!r.ok)throw Error(data?.detail||`خطأ من الخادم (${r.status})`);return data}
function can(p){return !!S.me?.is_group_admin || (S.me?.permissions||[]).includes(p)}
function requireCompany(){if(!S.companyId)throw Error('اختر الشركة من أعلى الصفحة')}
function options(items,val,name,empty='اختر'){return `<option value="">${empty}</option>`+items.map(x=>`<option value="${x[val]}">${esc(x[name])}</option>`).join('')}
function accountOptions(filter){const a=filter?S.accounts.filter(filter):S.accounts;return options(a,'account_id','display','اختر الحساب')}
function companyOptions(){return options(S.companies,'company_id','company_name','اختر الشركة')}
function currencyOptions(selected='EGP'){return S.currencies.map(c=>`<option value="${c.currency_code}" ${c.currency_code===selected?'selected':''}>${c.currency_code} — ${esc(c.currency_name_ar)}</option>`).join('')}
function badge(s){const c=['POSTED','PAID','OPEN','ACTIVE'].includes(s)?'badge-ok':['DRAFT','PARTIALLY_PAID'].includes(s)?'badge-warn':['CLOSED','LOCKED','CANCELLED','INACTIVE'].includes(s)?'badge-bad':'';const labels={POSTED:'مرحلة',PAID:'مسددة',PARTIALLY_PAID:'مسددة جزئياً',DRAFT:'مسودة',CANCELLED:'ملغاة'};return `<span class="badge ${c}">${esc(labels[s]||s)}</span>`}
function paymentLabel(m){return ({CREDIT:'آجل',CASH:'نقدي',BANK:'بنك'})[m]||m||'آجل'}
function openModal(title,html,onSubmit){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;S.modalSubmit=onSubmit;$('modalBg').classList.add('open')}
function closeModal(){$('modalBg').classList.remove('open');S.modalSubmit=null;$('modalForm').reset()}

async function loadSystemBrand(){try{S.systemInfo=await api('/api/system-info');const name=S.systemInfo?.group_name||'Holding ERP';if($('loginGroupName'))$('loginGroupName').textContent=name;if($('sideGroupName'))$('sideGroupName').textContent=name;document.title=`${name} ERP`}catch{} }
function refreshBrand(){const name=S.me?.group_name||S.systemInfo?.group_name||'Holding ERP';if($('loginGroupName'))$('loginGroupName').textContent=name;if($('sideGroupName'))$('sideGroupName').textContent=name;document.title=`${name} ERP`}
function safeFileName(v){return String(v||'report').replace(/[\\/:*?"<>|]+/g,'-').replace(/\s+/g,'_')}
function cleanTableForExport(table){const clone=table.cloneNode(true);clone.querySelectorAll('button,input,select,textarea').forEach(el=>{const span=document.createElement('span');span.textContent=el.tagName==='SELECT'?el.options[el.selectedIndex]?.text||'':el.value||el.textContent||'';el.replaceWith(span)});const headers=[...clone.querySelectorAll('thead th')];headers.forEach((th,i)=>{if(/الإجراءات|إجراء/.test(th.textContent)){clone.querySelectorAll('tr').forEach(tr=>tr.children[i]?.remove())}});return clone.outerHTML}
function exportTablesExcel(title,tables){if(!tables.length)throw Error('لا توجد بيانات ظاهرة للتصدير');const company=S.companies.find(c=>c.company_id===S.companyId);const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"><style>table{border-collapse:collapse;margin:12px 0}th,td{border:1px solid #777;padding:6px}th{background:#eaf1f7}</style></head><body dir="rtl"><h2>${esc(S.me?.group_name||'Holding ERP')}</h2><h3>${esc(company?.company_name||'المجموعة')}</h3><h1>${esc(title)}</h1>${tables.map(cleanTableForExport).join('<br>')}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(title)}_${today()}.xls`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportActivePageExcel(){const page=$(`page-${S.page}`);const tables=[...page.querySelectorAll('table')].filter(t=>t.offsetParent!==null&&t.querySelector('tbody tr'));exportTablesExcel(info[S.page]?.[0]||'تقرير',tables)}
function printActivePage(){const page=$(`page-${S.page}`);const clone=page.cloneNode(true);clone.querySelectorAll('.toolbar button,.no-print,button,input,select,textarea').forEach(el=>el.remove());printWindow(info[S.page]?.[0]||'تقرير',clone.innerHTML)}

async function login(e){e.preventDefault();$('loginError').textContent='';try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('loginEmail').value,password:$('loginPassword').value})});S.token=d.access_token;localStorage.erp_token=S.token;await boot()}catch(x){$('loginError').textContent=x.message}}
function logout(show=true){S.token='';localStorage.removeItem('erp_token');$('app').classList.add('hidden');$('loginScreen').classList.remove('hidden');if(show)toast('تم تسجيل الخروج')}
async function boot(){try{[S.me,S.companies,S.currencies,S.settings]=await Promise.all([api('/api/me'),api('/api/companies'),api('/api/currencies'),api('/api/system-settings')]);refreshBrand();if(!S.companyId||!S.companies.some(c=>c.company_id===S.companyId))S.companyId=S.companies[0]?.company_id||'';localStorage.erp_company=S.companyId;$('companySelect').innerHTML=companyOptions();$('companySelect').value=S.companyId;$('userEmail').textContent=S.me.email;$('userRole').textContent=S.me.is_group_admin?'مدير المجموعة':S.me.role_code;$('loginScreen').classList.add('hidden');$('app').classList.remove('hidden');applyPermissions();await loadContext();await showPage('dashboard')}catch(e){logout(false);$('loginError').textContent=e.message}}
function applyPermissions(){const map={newGroupAccount:'ACCOUNT_MANAGE',newCompanyAccount:'ACCOUNT_MANAGE',applyProfessionalChart:'ACCOUNT_MANAGE',newCurrency:'CURRENCY_MANAGE',newRate:'CURRENCY_MANAGE',newOpening:'OPENING_BALANCE_CREATE',newVoucher:'VOUCHER_CREATE',newUser:'USER_MANAGE'};Object.entries(map).forEach(([id,p])=>{if($(id))$(id).classList.toggle('hidden',!can(p))});if($('editGroupProfile'))$('editGroupProfile').classList.toggle('hidden',!S.me?.is_group_admin);if($('newCompany'))$('newCompany').classList.toggle('hidden',!S.me?.is_group_admin)}
async function loadContext(){if(!S.companyId){S.accounts=[];S.parties=[];S.banks=[];S.assetCategories=[];S.assets=[];return}const [a,p,b,ac,fa]=await Promise.all([api(`/api/accounts?company_id=${S.companyId}`),api(`/api/parties?company_id=${S.companyId}`),api(`/api/bank-accounts?company_id=${S.companyId}`),api(`/api/asset-categories?company_id=${S.companyId}`),api(`/api/assets?company_id=${S.companyId}`)]);S.accounts=a.map(x=>({...x,display:`${x.local_account_code} — ${x.local_account_name}`}));S.parties=p;S.banks=b;S.assetCategories=ac;S.assets=fa;if($('reportAccount'))$('reportAccount').innerHTML=accountOptions()}

async function voucherPostedAction(id,action){const labels={reverse:'عكس القيد',correct:'تصحيح القيد', 'unpost-test':'إرجاع القيد لمسودة للاختبار'};const reason=prompt(`سبب ${labels[action]} (إلزامي):`);if(!reason||reason.trim().length<3)return;const action_date=prompt('تاريخ العملية YYYY-MM-DD:',today());if(!action_date)return;if(action==='unpost-test'&&!confirm('هذه عملية اختبار استثنائية وتضعف أثر المراجعة. هل أنت متأكد؟'))return;const r=await api(`/api/vouchers/${id}/${action}`,{method:'POST',body:JSON.stringify({reason:reason.trim(),action_date})});toast(r.message||'تمت العملية');await loaders[S.page]()}
async function resetCompanyData(id){const preview=await api(`/api/companies/${id}/reset-preview`);if(!preview.enabled)throw Error('فعّل ALLOW_COMPANY_RESET=true في Render أثناء التجربة فقط');const full=confirm('OK = تصفير كامل مع الاحتفاظ بالشركة والمستخدمين وشجرة الحسابات. Cancel = تصفير الحركات المالية فقط.');const mode=full?'FULL_PRESERVE_CHART':'FINANCIAL_ONLY';const reason=prompt('اكتب سبب التصفير:');if(!reason||reason.trim().length<5)return;const typed=prompt(`اكتب عبارة التأكيد كما هي:
${preview.confirmation_text}`);if(typed!==preview.confirmation_text){toast('عبارة التأكيد غير مطابقة',true);return}if(!confirm(`سيتم حذف البيانات المختارة نهائياً من ${preview.company.company_name}. لا يمكن التراجع. متابعة؟`))return;const r=await api(`/api/companies/${id}/reset-data`,{method:'POST',body:JSON.stringify({mode,reason:reason.trim(),confirmation_text:typed})});toast(r.message);await loadCompanies();await loadContext()}

const info={dashboard:['لوحة التحكم','نظرة عامة على المجموعة'],companies:['الشركات','هيكل المجموعة'],periods:['الفترات المالية','الإغلاق الشهري'],chart:['دليل الحسابات','حسابات رئيسية وفرعية'],currencies:['العملات','أسعار الصرف والتقييم'],opening:['الأرصدة الافتتاحية','بداية التشغيل لكل شركة'],vouchers:['قيود اليومية','مسودات وترحيل وصلاحيات'],customers:['العملاء','الذمم المدينة'],vendors:['الموردون','الذمم الدائنة'],sales:['المبيعات','فواتير العملاء'],purchases:['المشتريات','فواتير الموردين'],banks:['البنوك','عملات وقبض وصرف'],assets:['الأصول الثابتة','سجل الأصول والإهلاك'],reports:['التقارير','القوائم المالية والطباعة'],consolidated:['التقارير المجمعة','جميع شركات المجموعة'],users:['المستخدمون','الصلاحيات والأدوار'],audit:['سجل التدقيق','تاريخ العمليات']};
async function showPage(p){S.page=p;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${p}`));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageTitle').textContent=info[p][0];$('pageSub').textContent=info[p][1];$('side').classList.remove('open');try{await loaders[p]?.()}catch(e){toast(e.message,true)}}
const loaders={dashboard:loadDashboard,companies:loadCompanies,periods:loadPeriods,chart:loadChart,currencies:loadCurrencies,opening:loadOpening,vouchers:loadVouchers,customers:()=>loadParties('CUSTOMER'),vendors:()=>loadParties('VENDOR'),sales:()=>loadInvoices('SALES'),purchases:()=>loadInvoices('PURCHASE'),banks:loadBanks,assets:loadAssets,reports:()=>{},consolidated:loadConsolidated,users:loadUsers,audit:loadAudit};

async function loadDashboard(){const d=await api(`/api/dashboard${S.companyId?`?company_id=${S.companyId}`:''}`);$('dCompanies').textContent=d.group.companies;$('dUsers').textContent=d.group.users;$('dSales').textContent=fmt(d.company.sales);$('dPurchases').textContent=fmt(d.company.purchases);const c=S.companies.find(x=>x.company_id===S.companyId);$('activeCompanyInfo').innerHTML=c?`<h3>${esc(c.company_name)}</h3><p>الكود: <b>${esc(c.company_code)}</b> — العملة: <b>${esc(c.functional_currency)}</b></p><p>العملاء والموردون: <b>${d.company.parties||0}</b> — الأصول: <b>${d.company.assets||0}</b></p>`:'اختر شركة.'}
async function loadCompanies(){S.companies=await api('/api/companies');$('companiesBody').innerHTML=S.companies.map(c=>`<tr><td>${esc(c.company_code)}</td><td><b>${esc(c.company_name)}</b></td><td>${badge(c.company_kind)}</td><td class="money">${fmt(c.ownership_percent)}%</td><td>${esc(c.functional_currency)}</td><td><div class="action-cell">${S.me?.is_group_admin?`<button class="btn btn-small btn-light editCompany" data-id="${c.company_id}">تعديل</button>${S.settings.allow_company_reset?`<button class="btn btn-small btn-danger resetCompany" data-id="${c.company_id}">تصفير بيانات</button>`:''}`:''}</div></td></tr>`).join('')||`<tr><td colspan="6" class="empty">لا توجد شركات</td></tr>`;$('companySelect').innerHTML=companyOptions();$('companySelect').value=S.companyId;document.querySelectorAll('.editCompany').forEach(b=>b.onclick=()=>editCompany(b.dataset.id));document.querySelectorAll('.resetCompany').forEach(b=>b.onclick=()=>resetCompanyData(b.dataset.id))}
async function loadPeriods(){requireCompany();const [years,periods]=await Promise.all([api(`/api/fiscal-years?company_id=${S.companyId}`),api(`/api/fiscal-periods?company_id=${S.companyId}`)]);$('yearsBody').innerHTML=years.map(y=>`<tr><td>${esc(y.year_name)}</td><td>${y.start_date}</td><td>${y.end_date}</td><td>${badge(y.status)}</td></tr>`).join('');$('periodsBody').innerHTML=periods.map(p=>`<tr><td>${esc(p.period_name)}</td><td>${p.start_date}</td><td>${p.end_date}</td><td>${badge(p.status)}</td><td><button class="btn btn-small btn-light periodToggle" data-id="${p.period_id}" data-status="${p.status==='OPEN'?'CLOSED':'OPEN'}">${p.status==='OPEN'?'إغلاق':'فتح'}</button></td></tr>`).join('');document.querySelectorAll('.periodToggle').forEach(b=>b.onclick=async()=>{await api(`/api/fiscal-periods/${b.dataset.id}?new_status=${b.dataset.status}`,{method:'PATCH'});toast('تم تحديث الفترة');loadPeriods()})}
async function loadChart(){S.groupAccounts=await api('/api/group-accounts');if(S.chartTab==='group'){$('chartHead').innerHTML='<tr><th>الكود</th><th>الحساب</th><th>التصنيف</th><th>النوع</th><th>الحساب الرئيسي</th><th>الإجراءات</th></tr>';$('chartBody').innerHTML=S.groupAccounts.map(a=>`<tr><td>${a.account_code}</td><td class="account-tree"><span class="tree-indent" style="--level:${a.account_level||0}"></span>${a.is_postable?'•':'▰'} <b>${esc(a.account_name)}</b></td><td>${esc(a.account_class)}</td><td>${a.is_postable?'<span class="badge badge-ok">حركة</span>':'<span class="badge">رئيسي</span>'}</td><td>${esc(a.parent_account_name||'—')}</td><td><div class="action-cell">${can('ACCOUNT_MANAGE')?`<button class="btn btn-small btn-light editGA" data-id="${a.group_account_id}">تعديل</button><button class="btn btn-small btn-danger deleteGA" data-id="${a.group_account_id}">حذف</button>`:''}</div></td></tr>`).join('');document.querySelectorAll('.editGA').forEach(b=>b.onclick=()=>editGA(b.dataset.id));document.querySelectorAll('.deleteGA').forEach(b=>b.onclick=()=>deleteGA(b.dataset.id))}else{requireCompany();$('chartHead').innerHTML='<tr><th>الكود</th><th>الحساب المحلي</th><th>كود المجموعة</th><th>التصنيف</th></tr>';$('chartBody').innerHTML=S.accounts.map(a=>`<tr><td>${a.local_account_code}</td><td>${esc(a.local_account_name)}</td><td>${a.group_account_code}</td><td>${esc(a.account_class)}</td></tr>`).join('')}}
async function loadCurrencies(){[S.currencies,S.rates]=await Promise.all([api('/api/currencies'),api(`/api/exchange-rates${S.companyId?`?company_id=${S.companyId}`:''}`)]);$('currenciesBody').innerHTML=S.currencies.map(c=>`<tr><td><b>${c.currency_code}</b></td><td>${esc(c.currency_name_ar)}</td><td>${esc(c.symbol||'—')}</td><td>${c.is_base?badge('ACTIVE'):'—'}</td></tr>`).join('');$('ratesBody').innerHTML=S.rates.slice(0,50).map(r=>`<tr><td>${r.rate_date}</td><td>${r.from_currency}/${r.to_currency}</td><td>${r.rate_type}</td><td class="money">${fmt(r.rate,6)}</td><td>${r.company_id?'شركة':'المجموعة'}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">لا توجد أسعار صرف</td></tr>`}
async function loadOpening(){requireCompany();const rows=await api(`/api/opening-balances?company_id=${S.companyId}`);$('openingBody').innerHTML=rows.map(x=>`<tr><td>${esc(x.batch_no)}</td><td>${x.opening_date}</td><td>${esc(x.description||'')}</td><td class="money">${fmt(x.total_debit)}</td><td class="money">${fmt(x.total_credit)}</td><td>${badge(x.status)}</td><td>${voucherActions(x)}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">لم تُدخل أرصدة افتتاحية</td></tr>`;wireVoucherActions()}
async function loadVouchers(){requireCompany();const rows=await api(`/api/vouchers?company_id=${S.companyId}`);$('vouchersBody').innerHTML=rows.map(v=>`<tr><td>${esc(v.voucher_no)}</td><td>${v.posting_date}</td><td>${esc(v.voucher_type||v.source_module)}</td><td>${esc(v.description||'')}</td><td class="money">${fmt(v.amount)}</td><td>${badge(v.status)}</td><td>${voucherActions(v)}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">لا توجد قيود</td></tr>`;wireVoucherActions()}
function voucherActions(v){return `<div class="actions"><button class="btn btn-small btn-light vprint" data-id="${v.voucher_id}">طباعة</button>${v.is_reversed?'<span class="badge badge-bad">تم عكسه</span>':''}${v.status==='DRAFT'&&can('VOUCHER_EDIT')?`<button class="btn btn-small btn-light vedit" data-id="${v.voucher_id}">تعديل</button>`:''}${v.status==='DRAFT'&&can('VOUCHER_POST')?`<button class="btn btn-small btn-success vpost" data-id="${v.voucher_id}">ترحيل</button>`:''}${v.status==='DRAFT'&&can('VOUCHER_DELETE')?`<button class="btn btn-small btn-danger vdelete" data-id="${v.voucher_id}">حذف</button>`:''}${v.status==='POSTED'&&!v.is_reversed&&['GL','OPENING'].includes(v.source_module)&&can('VOUCHER_REVERSE')?`<button class="btn btn-small btn-warn vreverse" data-id="${v.voucher_id}">عكس</button><button class="btn btn-small btn-light vcorrect" data-id="${v.voucher_id}">تصحيح</button>`:''}${v.status==='POSTED'&&!v.is_reversed&&v.source_module==='GL'&&S.settings.allow_test_unpost?`<button class="btn btn-small btn-danger vunpost" data-id="${v.voucher_id}">إرجاع لمسودة (تجربة)</button>`:''}</div>`}
function wireVoucherActions(){document.querySelectorAll('.vprint').forEach(b=>b.onclick=()=>printVoucher(b.dataset.id));document.querySelectorAll('.vedit').forEach(b=>b.onclick=()=>openVoucherEditor(b.dataset.id));document.querySelectorAll('.vpost').forEach(b=>b.onclick=async()=>{if(!confirm('بعد الترحيل يتم التصحيح بقيد عكس وليس بتغيير السجل الأصلي. متابعة؟'))return;await api(`/api/vouchers/${b.dataset.id}/post`,{method:'POST'});toast('تم ترحيل القيد');await loaders[S.page]()});document.querySelectorAll('.vdelete').forEach(b=>b.onclick=async()=>{if(!confirm('حذف المسودة نهائياً؟'))return;await api(`/api/vouchers/${b.dataset.id}`,{method:'DELETE'});toast('تم حذف المسودة');await loaders[S.page]()});document.querySelectorAll('.vreverse').forEach(b=>b.onclick=()=>voucherPostedAction(b.dataset.id,'reverse'));document.querySelectorAll('.vcorrect').forEach(b=>b.onclick=()=>voucherPostedAction(b.dataset.id,'correct'));document.querySelectorAll('.vunpost').forEach(b=>b.onclick=()=>voucherPostedAction(b.dataset.id,'unpost-test'))}
async function loadParties(type){requireCompany();const r=await api(`/api/parties?company_id=${S.companyId}&party_type=${type}`);S.parties=await api(`/api/parties?company_id=${S.companyId}`);const id=type==='CUSTOMER'?'customersBody':'vendorsBody';$(id).innerHTML=r.map(p=>`<tr><td>${esc(p.party_code)}</td><td><b>${esc(p.party_name)}</b></td><td>${esc(p.tax_registration_no||'—')}</td><td>${esc(p.phone||'—')}</td>${type==='CUSTOMER'?`<td class="money">${fmt(p.credit_limit)}</td>`:''}<td>${p.payment_terms_days} يوم</td></tr>`).join('')||`<tr><td colspan="6" class="empty">لا توجد بيانات</td></tr>`}
async function loadInvoices(type){requireCompany();const r=await api(`/api/invoices?company_id=${S.companyId}&invoice_type=${type}`),id=type==='SALES'?'salesBody':'purchasesBody';$(id).innerHTML=r.map(i=>{const outstanding=Number(i.outstanding_amount||0);const actions=[`<button class="btn btn-small btn-light iprint" data-id="${i.invoice_id}">طباعة</button>`];if(i.status==='DRAFT'&&can('VOUCHER_POST'))actions.unshift(`<button class="btn btn-small btn-primary ipost" data-id="${i.invoice_id}">ترحيل</button>`);if(outstanding>0&&['POSTED','PARTIALLY_PAID'].includes(i.status))actions.unshift(`<button class="btn btn-small btn-success ipay" data-id="${i.invoice_id}" data-type="${type}">سداد</button>`);return `<tr><td>${esc(i.invoice_no)}</td><td>${i.invoice_date}</td><td>${esc(i.party_name)}</td><td>${paymentLabel(i.payment_method)}</td><td>${i.currency} @ ${fmt(i.exchange_rate,6)}</td><td class="money">${fmt(i.total_amount)}</td><td class="money">${fmt(i.paid_amount)}</td><td class="money"><b>${fmt(outstanding)}</b></td><td>${badge(i.status)}</td><td>${actions.join(' ')}</td></tr>`}).join('')||`<tr><td colspan="10" class="empty">لا توجد فواتير</td></tr>`;document.querySelectorAll('.iprint').forEach(b=>b.onclick=()=>printInvoice(b.dataset.id));document.querySelectorAll('.ipay').forEach(b=>b.onclick=()=>newInvoicePayment(b.dataset.id,b.dataset.type).catch(e=>toast(e.message,true)));document.querySelectorAll('.ipost').forEach(b=>b.onclick=()=>postInvoice(b.dataset.id).catch(e=>toast(e.message,true)))}
async function loadBanks(){requireCompany();[S.banks,S.cash]=await Promise.all([api(`/api/bank-accounts?company_id=${S.companyId}`),api(`/api/cash-transactions?company_id=${S.companyId}`)]);$('banksBody').innerHTML=S.banks.map(b=>`<tr><td>${esc(b.bank_code)}</td><td>${esc(b.bank_name)}<br><small>${esc(b.account_name)}</small></td><td>${b.currency}</td><td class="money"><b>${fmt(b.current_balance)}</b></td><td class="money">${fmt(b.current_balance_base)}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">لا توجد حسابات بنكية</td></tr>`;$('cashBody').innerHTML=S.cash.slice(0,30).map(t=>`<tr><td>${t.transaction_type==='RECEIPT'?'<span class="badge badge-ok">قبض</span>':'<span class="badge badge-warn">صرف</span>'}</td><td>${esc(t.transaction_no)}</td><td>${t.transaction_date}</td><td>${esc(t.party_name||'—')}</td><td class="money">${fmt(t.amount)}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">لا توجد حركات</td></tr>`}
async function loadAssets(){requireCompany();[S.assetCategories,S.assets]=await Promise.all([api(`/api/asset-categories?company_id=${S.companyId}`),api(`/api/assets?company_id=${S.companyId}`)]);$('assetCatsBody').innerHTML=S.assetCategories.map(c=>`<tr><td>${esc(c.category_code)}</td><td>${esc(c.category_name)}</td><td>${c.useful_life_months} شهر</td></tr>`).join('');$('assetsBody').innerHTML=S.assets.map(a=>`<tr><td>${esc(a.asset_code)}</td><td><b>${esc(a.asset_name)}</b></td><td>${esc(a.category_name)}</td><td class="money">${fmt(a.acquisition_cost)}</td><td class="money">${fmt(a.accumulated_depreciation)}</td><td class="money"><b>${fmt(a.net_book_value)}</b></td></tr>`).join('')||`<tr><td colspan="6" class="empty">لا توجد أصول</td></tr>`}
async function loadConsolidated(){const rows=await api(`/api/consolidated-trial-balance?as_of_date=${$('reportTo').value||today()}`),codes=[...new Set(rows.flatMap(r=>Object.keys(r.companies)))].sort();$('consolidatedHead').innerHTML=`<tr><th>الكود</th><th>الحساب</th>${codes.map(c=>`<th>${c}</th>`).join('')}<th>المجمع</th></tr>`;$('consolidatedBody').innerHTML=rows.map(r=>`<tr><td>${r.account_code}</td><td>${esc(r.account_name)}</td>${codes.map(c=>`<td class="money">${fmt(r.companies[c]||0)}</td>`).join('')}<td class="money"><b>${fmt(r.consolidated_net)}</b></td></tr>`).join('')||`<tr><td class="empty">لا توجد حركات</td></tr>`}
async function loadUsers(){S.users=await api('/api/users');$('usersBody').innerHTML=S.users.map(u=>`<tr><td>${esc(u.full_name||'—')}</td><td>${esc(u.email)}</td><td>${esc(u.is_group_admin?'GROUP_ADMIN':u.role_code)}</td><td>${esc(u.company_name||'كل المجموعة')}</td><td><small>${esc((u.permissions||[]).join(', ')||'صلاحيات الدور')}</small></td><td>${u.is_active?badge('ACTIVE'):badge('INACTIVE')}</td><td><div class="action-cell"><button class="btn btn-small btn-light editUser" data-id="${u.user_id}">تعديل</button>${u.user_id!==S.me?.user_id?`<button class="btn btn-small btn-danger deleteUser" data-id="${u.user_id}">حذف</button>`:''}</div></td></tr>`).join('');document.querySelectorAll('.editUser').forEach(b=>b.onclick=()=>editUser(b.dataset.id));document.querySelectorAll('.deleteUser').forEach(b=>b.onclick=()=>deleteUser(b.dataset.id))}
async function loadAudit(){const r=await api('/api/audit-log');$('auditBody').innerHTML=r.map(a=>`<tr><td>${new Date(a.created_at).toLocaleString('ar-EG')}</td><td>${esc(a.full_name||a.email||'—')}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type)}</td><td>${esc(a.company_name||'—')}</td><td><small>${esc(JSON.stringify(a.details||{}))}</small></td></tr>`).join('')}

function editGroupProfile(){openModal('تعديل اسم المجموعة المالكة',`<div class="field"><label>اسم المجموعة</label><input name="name" value="${esc(S.me?.group_name||'')}" required></div>`,async f=>{const r=await api('/api/group-profile',{method:'PATCH',body:JSON.stringify({group_name:f.get('name')})});S.me.group_name=r.group_name;refreshBrand();return {message:'تم تعديل اسم المجموعة'}})}
function editCompany(id){const c=S.companies.find(x=>x.company_id===id);if(!c)return;openModal('تعديل بيانات الشركة',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" value="${esc(c.company_code)}" required></div><div class="field"><label>اسم الشركة</label><input name="name" value="${esc(c.company_name)}" required></div><div class="field"><label>الاسم القانوني</label><input name="legal" value="${esc(c.legal_name||c.company_name)}"></div><div class="field"><label>نسبة الملكية</label><input name="own" type="number" step="0.0001" value="${c.ownership_percent}"></div><div class="field"><label>الشركة الأم</label><select name="parent">${companyOptions()}</select></div><div class="field"><label>العملة</label><select name="currency">${currencyOptions(c.functional_currency)}</select></div><div class="field"><label>الحالة</label><select name="active"><option value="true" ${c.is_active!==false?'selected':''}>نشطة</option><option value="false" ${c.is_active===false?'selected':''}>موقوفة</option></select></div></div>`,f=>api(`/api/companies/${id}`,{method:'PATCH',body:JSON.stringify({company_code:f.get('code'),company_name:f.get('name'),legal_name:f.get('legal')||f.get('name'),parent_company_id:c.company_kind==='HOLDING'?null:(f.get('parent')||c.parent_company_id),ownership_percent:Number(f.get('own')||100),functional_currency:f.get('currency'),is_active:f.get('active')==='true'})}));setTimeout(()=>{const x=document.querySelector('#modalForm [name=parent]');if(x)x.value=c.parent_company_id||''},0)}
function editGA(id){const a=S.groupAccounts.find(x=>x.group_account_id===id);if(!a)return;const parents=S.groupAccounts.filter(x=>x.group_account_id!==id).map(x=>({...x,display:`${'— '.repeat(x.account_level||0)}${x.account_code} — ${x.account_name}`}));openModal('تعديل حساب المجموعة',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" value="${esc(a.account_code)}" required></div><div class="field"><label>الاسم</label><input name="name" value="${esc(a.account_name)}" required></div><div class="field"><label>التصنيف</label><select name="cls"><option>ASSET</option><option>LIABILITY</option><option>EQUITY</option><option>REVENUE</option><option>EXPENSE</option></select></div><div class="field"><label>الطبيعة</label><select name="normal"><option>DEBIT</option><option>CREDIT</option></select></div><div class="field full"><label>الحساب الرئيسي</label><select name="parent">${options(parents,'group_account_id','display','بدون حساب رئيسي')}</select></div><div class="field"><label>نوع الحساب</label><select name="kind"><option value="main">رئيسي / تجميعي</option><option value="postable">حركة / يقبل القيود</option></select></div><div class="field"><label>الحالة</label><select name="active"><option value="true">نشط</option><option value="false">موقوف</option></select></div></div>`,f=>api(`/api/group-accounts/${id}`,{method:'PATCH',body:JSON.stringify({account_code:f.get('code'),account_name:f.get('name'),account_class:f.get('cls'),normal_balance:f.get('normal'),parent_group_account_id:f.get('parent')||null,is_postable:f.get('kind')==='postable',is_active:f.get('active')==='true'})}));setTimeout(()=>{const q=n=>document.querySelector(`#modalForm [name=${n}]`);q('cls').value=a.account_class;q('normal').value=a.normal_balance;q('parent').value=a.parent_group_account_id||'';q('kind').value=a.is_postable?'postable':'main';q('active').value=a.is_active===false?'false':'true'},0)}
async function deleteGA(id){if(!confirm('حذف/إيقاف هذا الحساب؟ لن يسمح النظام بالحذف إذا كان تحته فروع أو مرتبطاً بحساب شركة.'))return;try{const r=await api(`/api/group-accounts/${id}`,{method:'DELETE'});toast(r.message);loadChart()}catch(e){toast(e.message,true)}}
async function applyProfessionalChart(){if(!confirm('سيتم إضافة نموذج شجرة حسابات تفصيلي متعدد المستويات وربط حسابات الحركة بالشركات. الحسابات والقيود الحالية لن تُحذف. متابعة؟'))return;try{const r=await api('/api/group-accounts/apply-professional-template',{method:'POST'});toast(`${r.message} — أضيف ${r.accounts_added} حساب`);await loadContext();loadChart()}catch(e){toast(e.message,true)}}
function newCompany(){openModal('شركة جديدة',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" required></div><div class="field"><label>اسم الشركة</label><input name="name" required></div><div class="field"><label>النوع</label><select name="kind"><option value="SUBSIDIARY">شركة تابعة</option><option value="HOLDING">قابضة</option><option value="ELIMINATION">استبعادات</option></select></div><div class="field"><label>الشركة الأم</label><select name="parent">${companyOptions()}</select></div><div class="field"><label>نسبة الملكية</label><input name="own" type="number" value="100"></div><div class="field"><label>العملة</label><select name="currency">${currencyOptions()}</select></div></div>`,f=>api('/api/companies',{method:'POST',body:JSON.stringify({company_code:f.get('code'),company_name:f.get('name'),company_kind:f.get('kind'),parent_company_id:f.get('parent')||null,ownership_percent:Number(f.get('own')||100),functional_currency:f.get('currency')})}))}
function newFY(){requireCompany();const y=new Date().getFullYear();openModal('سنة مالية جديدة',`<div class="form-grid"><div class="field"><label>اسم السنة</label><input name="name" value="${y}" required></div><div class="field"><label>البداية</label><input name="start" type="date" value="${y}-01-01" required></div><div class="field"><label>النهاية</label><input name="end" type="date" value="${y}-12-31" required></div></div>`,f=>api('/api/fiscal-years',{method:'POST',body:JSON.stringify({company_id:S.companyId,year_name:f.get('name'),start_date:f.get('start'),end_date:f.get('end')})}))}
function newGA(){const parents=S.groupAccounts.map(a=>({...a,display:`${'— '.repeat(a.account_level||0)}${a.account_code} — ${a.account_name} ${a.is_postable?'(حركة)':'(رئيسي)'}`}));openModal('حساب مجموعة جديد',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" required></div><div class="field"><label>الاسم</label><input name="name" required></div><div class="field"><label>التصنيف</label><select name="cls"><option>ASSET</option><option>LIABILITY</option><option>EQUITY</option><option>REVENUE</option><option>EXPENSE</option></select></div><div class="field"><label>الطبيعة</label><select name="normal"><option>DEBIT</option><option>CREDIT</option></select></div><div class="field full"><label>الحساب الرئيسي (اتركه فارغاً لإنشاء كود رئيسي على أعلى مستوى)</label><select name="parent">${options(parents,'group_account_id','display','بدون حساب رئيسي')}</select></div><div class="field full"><label>نوع الحساب</label><select name="kind"><option value="main">حساب رئيسي / تجميعي — لا يقبل قيوداً</option><option value="postable">حساب حركة / فرعي — يقبل القيود</option></select></div></div>`,f=>api('/api/group-accounts',{method:'POST',body:JSON.stringify({account_code:f.get('code'),account_name:f.get('name'),account_class:f.get('cls'),normal_balance:f.get('normal'),parent_group_account_id:f.get('parent')||null,is_postable:f.get('kind')==='postable',is_intercompany:false,intercompany_role:'NONE'})}))}
function newCA(){requireCompany();const postable=S.groupAccounts.filter(a=>a.is_postable).map(a=>({...a,display:`${a.account_code} — ${a.account_name}`}));openModal('حساب شركة جديد',`<div class="form-grid"><div class="field full"><label>حساب المجموعة (حركة فقط)</label><select name="ga" required>${options(postable,'group_account_id','display')}</select></div><div class="field"><label>الكود المحلي</label><input name="code" required></div><div class="field"><label>الاسم المحلي</label><input name="name" required></div></div>`,f=>api('/api/accounts',{method:'POST',body:JSON.stringify({company_id:S.companyId,group_account_id:f.get('ga'),local_account_code:f.get('code'),local_account_name:f.get('name')})}))}
function newCurrency(){openModal('عملة جديدة',`<div class="form-grid"><div class="field"><label>الكود ISO</label><input name="code" maxlength="3" required></div><div class="field"><label>الاسم العربي</label><input name="ar" required></div><div class="field"><label>الاسم الإنجليزي</label><input name="en"></div><div class="field"><label>الرمز</label><input name="symbol"></div></div>`,f=>api('/api/currencies',{method:'POST',body:JSON.stringify({currency_code:f.get('code').toUpperCase(),currency_name_ar:f.get('ar'),currency_name_en:f.get('en')||null,symbol:f.get('symbol')||null,decimal_places:2})}))}
function newRate(){openModal('سعر صرف جديد',`<div class="form-grid"><div class="field"><label>العملة</label><select name="currency">${currencyOptions('USD')}</select></div><div class="field"><label>التاريخ</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>نوع السعر</label><select name="type"><option value="SPOT">سعر معاملة</option><option value="AVERAGE">متوسط</option><option value="CLOSING">إقفال / تقييم</option></select></div><div class="field"><label>السعر مقابل EGP</label><input name="rate" type="number" step="0.000001" required></div><div class="field"><label>النطاق</label><select name="scope"><option value="">المجموعة كلها</option><option value="company">الشركة المختارة</option></select></div><div class="field"><label>المصدر</label><input name="source"></div></div>`,f=>api('/api/exchange-rates',{method:'POST',body:JSON.stringify({company_id:f.get('scope')==='company'?S.companyId:null,rate_date:f.get('date'),from_currency:f.get('currency'),rate_type:f.get('type'),rate:Number(f.get('rate')),source:f.get('source')||null,notes:null})}))}

function lineEditorHtml(prefix='v'){return `<div class="table-wrap"><table class="table line-table"><thead><tr><th>الحساب</th><th>البيان</th><th>مدين EGP</th><th>دائن EGP</th><th></th></tr></thead><tbody id="${prefix}Lines"></tbody></table></div><button id="${prefix}AddLine" type="button" class="btn btn-light">+ سطر</button><div class="totals-bar"><span>إجمالي المدين: <b id="${prefix}Debit">0.00</b></span><span>إجمالي الدائن: <b id="${prefix}Credit">0.00</b></span><span>الفرق: <b id="${prefix}Diff">0.00</b></span></div>`}
function setupLineEditor(prefix,entries=[]){const body=$(`${prefix}Lines`);function recalc(){const rows=[...body.children];const d=rows.reduce((s,r)=>s+Number(r.querySelector('.ld').value||0),0),c=rows.reduce((s,r)=>s+Number(r.querySelector('.lc').value||0),0);$(`${prefix}Debit`).textContent=fmt(d);$(`${prefix}Credit`).textContent=fmt(c);$(`${prefix}Diff`).textContent=fmt(d-c);$(`${prefix}Diff`).className=Math.abs(d-c)<.0001?'ok-text':'danger-text'}function add(e={}){const tr=document.createElement('tr');tr.innerHTML=`<td><select class="la" required>${accountOptions()}</select></td><td><input class="lx desc" value="${esc(e.entry_description||e.description||'')}"></td><td><input class="ld" type="number" step="0.01" value="${Number(e.debit_amount||0)||''}"></td><td><input class="lc" type="number" step="0.01" value="${Number(e.credit_amount||0)||''}"></td><td><button type="button" class="btn btn-danger btn-small">×</button></td>`;tr.querySelector('.la').value=e.account_id||'';tr.querySelector('button').onclick=()=>{tr.remove();recalc()};tr.querySelectorAll('input').forEach(i=>i.oninput=recalc);body.appendChild(tr);recalc()}$(`${prefix}AddLine`).onclick=()=>add();(entries.length?entries:[{},{}]).forEach(add);return ()=>[...body.children].filter(r=>Number(r.querySelector('.ld').value||0)||Number(r.querySelector('.lc').value||0)).map(r=>({account_id:r.querySelector('.la').value,description:r.querySelector('.lx').value||null,debit_amount:Number(r.querySelector('.ld').value||0),credit_amount:Number(r.querySelector('.lc').value||0),currency:'EGP',exchange_rate:1,foreign_debit:Number(r.querySelector('.ld').value||0),foreign_credit:Number(r.querySelector('.lc').value||0)}))}
async function openVoucherEditor(id=null){requireCompany();let v=null;if(id)v=await api(`/api/vouchers/${id}`);const locked=v?.voucher_type==='OPENING'?'readonly':'';openModal(id?'تعديل مسودة القيد':'قيد يومية جديد',`<div class="form-grid"><div class="field"><label>رقم القيد</label><input name="no" value="${esc(v?.voucher_no||'JV-'+Date.now().toString().slice(-6))}" ${locked} required></div><div class="field"><label>تاريخ المستند</label><input name="doc" type="date" value="${v?.document_date||today()}" ${locked} required></div><div class="field"><label>تاريخ الترحيل</label><input name="post" type="date" value="${v?.posting_date||today()}" ${locked} required></div><div class="field"><label>طريقة الحفظ</label><select name="action"><option value="draft">حفظ مؤقت كمسودة</option><option value="post">حفظ وترحيل نهائي</option></select></div><div class="field full"><label>البيان</label><input name="desc" value="${esc(v?.description||'')}"></div></div>${lineEditorHtml('v')}`,async f=>{const entries=getLines();if(!entries.length)throw Error('أضف سطراً واحداً على الأقل');const wantsPost=f.get('action')==='post';if(wantsPost){const d=entries.reduce((s,x)=>s+x.debit_amount,0),c=entries.reduce((s,x)=>s+x.credit_amount,0);if(entries.length<2||Math.abs(d-c)>.0001)throw Error('لا يمكن الترحيل قبل توازن المدين والدائن')}const payload={voucher_no:f.get('no'),document_date:f.get('doc'),posting_date:f.get('post'),description:f.get('desc')||null,entries};if(id){await api(`/api/vouchers/${id}`,{method:'PUT',body:JSON.stringify(payload)});if(wantsPost)await api(`/api/vouchers/${id}/post`,{method:'POST'});return {message:wantsPost?'تم تعديل وترحيل القيد':'تم حفظ تعديلات المسودة'}}return api('/api/vouchers',{method:'POST',body:JSON.stringify({company_id:S.companyId,...payload,post_immediately:wantsPost})})});let getLines;setTimeout(()=>{getLines=setupLineEditor('v',v?.entries||[])},0)}
function newOpening(){requireCompany();openModal('إدخال الأرصدة الافتتاحية',`<div class="form-grid"><div class="field"><label>رقم الدفعة</label><input name="no" value="OB-${new Date().getFullYear()}" required></div><div class="field"><label>تاريخ الافتتاح</label><input name="date" type="date" value="${new Date().getFullYear()}-01-01" required></div><div class="field"><label>طريقة الحفظ</label><select name="action"><option value="draft">حفظ مؤقت للمراجعة</option><option value="post">ترحيل الأرصدة نهائياً</option></select></div><div class="field"><label>البيان</label><input name="desc" value="أرصدة افتتاحية"></div></div>${lineEditorHtml('o')}`,async f=>{const entries=getLines();if(!entries.length)throw Error('أضف أرصدة');const wantsPost=f.get('action')==='post';if(wantsPost){const d=entries.reduce((s,x)=>s+x.debit_amount,0),c=entries.reduce((s,x)=>s+x.credit_amount,0);if(entries.length<2||Math.abs(d-c)>.0001)throw Error('الأرصدة الافتتاحية يجب أن تكون متوازنة قبل الترحيل')}return api('/api/opening-balances',{method:'POST',body:JSON.stringify({company_id:S.companyId,batch_no:f.get('no'),opening_date:f.get('date'),description:f.get('desc')||null,entries,post_immediately:wantsPost})})});let getLines;setTimeout(()=>{getLines=setupLineEditor('o')},0)}

function newParty(type){requireCompany();openModal(type==='CUSTOMER'?'عميل جديد':'مورد جديد',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" required></div><div class="field"><label>الاسم</label><input name="name" required></div><div class="field"><label>التسجيل الضريبي</label><input name="tax"></div><div class="field"><label>الهاتف</label><input name="phone"></div><div class="field"><label>البريد</label><input name="email" type="email"></div><div class="field"><label>شروط الدفع بالأيام</label><input name="terms" type="number" value="0"></div><div class="field full"><label>العنوان</label><input name="address"></div><div class="field full"><label>حساب المراقبة</label><select name="control" required>${accountOptions(a=>type==='CUSTOMER'?a.account_class==='ASSET':a.account_class==='LIABILITY')}</select></div></div>`,f=>api('/api/parties',{method:'POST',body:JSON.stringify({company_id:S.companyId,party_code:f.get('code'),party_name:f.get('name'),party_type:type,tax_registration_no:f.get('tax')||null,email:f.get('email')||null,phone:f.get('phone')||null,address:f.get('address')||null,receivable_account_id:type==='CUSTOMER'?f.get('control'):null,payable_account_id:type==='VENDOR'?f.get('control'):null,credit_limit:0,payment_terms_days:Number(f.get('terms')||0)})}))}
async function resolvedRate(currency,date){if(currency==='EGP')return 1;const r=await api(`/api/exchange-rates/resolve?currency_code=${currency}&rate_date=${date}&company_id=${S.companyId}`);return Number(r.rate)}

async function postInvoice(id){if(!confirm('ترحيل الفاتورة وإنشاء القيد المحاسبي؟'))return;const r=await api(`/api/invoices/${id}/post`,{method:'POST'});toast(r.message||'تم ترحيل الفاتورة');await loaders[S.page]()}
function newInvoice(type){requireCompany();const parties=S.parties.filter(p=>p.party_type===(type==='SALES'?'CUSTOMER':'VENDOR')||p.party_type==='BOTH');if(!parties.length)throw Error(type==='SALES'?'أنشئ عميلاً أولاً':'أنشئ مورداً أولاً');openModal(type==='SALES'?'فاتورة مبيعات':'فاتورة مشتريات',`<div class="form-grid"><div class="field"><label>رقم الفاتورة</label><input name="no" required></div><div class="field"><label>${type==='SALES'?'العميل':'المورد'}</label><select name="party" required>${options(parties,'party_id','party_name')}</select></div><div class="field"><label>التاريخ</label><input id="invDate" name="date" type="date" value="${today()}" required></div><div class="field"><label>الاستحقاق</label><input name="due" type="date" value="${today()}" required></div><div class="field"><label>طريقة السداد</label><select id="invPaymentMethod" name="payment_method"><option value="CREDIT">آجل — على حساب العميل/المورد</option><option value="CASH">نقدي — صندوق</option><option value="BANK">بنك — حساب بنكي</option></select></div><div id="invCashField" class="field hidden"><label>حساب الصندوق</label><select name="settlement_account">${accountOptions(a=>a.account_class==='ASSET')}</select></div><div id="invBankField" class="field hidden"><label>الحساب البنكي</label><select name="bank_account">${options(S.banks,'bank_account_id','account_name')}</select></div><div class="field"><label>العملة</label><select id="invCurrency" name="currency">${currencyOptions()}</select></div><div class="field"><label>سعر الصرف إلى EGP</label><input id="invRate" name="rate" type="number" step="0.000001" value="1" required><small class="muted">يمكن تعديل السعر يدوياً</small></div><div class="field"><label>حساب الضريبة</label><select name="taxaccount">${accountOptions(a=>type==='SALES'?a.account_class==='LIABILITY':a.account_class==='ASSET')}</select></div><div class="field"><label>حالة الحفظ</label><select name="post"><option value="true">إثبات وترحيل الفاتورة</option><option value="false">حفظ مسودة بدون قيد</option></select></div><div class="field full"><label>البيان</label><input name="desc"></div></div><div class="table-wrap"><table class="table line-table"><thead><tr><th>الوصف</th><th>الحساب</th><th>الكمية</th><th>السعر بالعملة</th><th>ضريبة %</th><th></th></tr></thead><tbody id="invoiceLines"></tbody></table></div><button id="addInvoiceLine" type="button" class="btn btn-light">+ بند</button>`,async f=>{const lines=[...$('invoiceLines').children].map(tr=>({description:tr.querySelector('.id').value,account_id:tr.querySelector('.ia').value,quantity:Number(tr.querySelector('.iq').value||1),unit_price:Number(tr.querySelector('.ip').value||0),tax_rate:Number(tr.querySelector('.it').value||0),cost_center_id:null}));if(!lines.length)throw Error('أضف بنداً واحداً على الأقل');const method=f.get('payment_method');return api('/api/invoices',{method:'POST',body:JSON.stringify({company_id:S.companyId,invoice_type:type,invoice_no:f.get('no'),party_id:f.get('party'),invoice_date:f.get('date'),due_date:f.get('due'),currency:f.get('currency'),exchange_rate:Number(f.get('rate')),description:f.get('desc')||null,tax_account_id:f.get('taxaccount')||null,payment_method:method,settlement_account_id:method==='CASH'?(f.get('settlement_account')||null):null,bank_account_id:method==='BANK'?(f.get('bank_account')||null):null,lines,post_immediately:f.get('post')==='true'})})});setTimeout(()=>{async function refresh(){try{$('invRate').value=await resolvedRate($('invCurrency').value,$('invDate').value)}catch(e){toast(e.message,true)}}function togglePayment(){const m=$('invPaymentMethod').value;$('invCashField').classList.toggle('hidden',m!=='CASH');$('invBankField').classList.toggle('hidden',m!=='BANK')}$('invPaymentMethod').onchange=togglePayment;$('invCurrency').onchange=refresh;$('invDate').onchange=refresh;togglePayment();function add(){const tr=document.createElement('tr');tr.innerHTML=`<td><input class="id desc" required></td><td><select class="ia" required>${accountOptions(a=>type==='SALES'?a.account_class==='REVENUE':['EXPENSE','ASSET'].includes(a.account_class))}</select></td><td><input class="iq" type="number" value="1" min="0.0001" step="0.0001"></td><td><input class="ip" type="number" step="0.01" min="0"></td><td><input class="it" type="number" step="0.01" value="14" min="0"></td><td><button type="button" class="btn btn-danger btn-small">×</button></td>`;tr.querySelector('button').onclick=()=>tr.remove();$('invoiceLines').appendChild(tr)}$('addInvoiceLine').onclick=add;add()},0)}

async function newInvoicePayment(invoiceId,type){requireCompany();const i=await api(`/api/invoices/${invoiceId}`);const remaining=Number(i.outstanding_amount||0);if(remaining<=0)throw Error('الفاتورة مسددة بالكامل');openModal(type==='SALES'?'تحصيل فاتورة عميل':'سداد فاتورة مورد',`<div class="notice"><b>${esc(i.party_name)}</b> — فاتورة ${esc(i.invoice_no)}<br>الإجمالي: ${fmt(i.total_amount)} ${i.currency} — المتبقي: <b>${fmt(remaining)} ${i.currency}</b></div><div class="form-grid"><div class="field"><label>رقم السند</label><input name="no" required></div><div class="field"><label>تاريخ السداد</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>طريقة السداد</label><select id="payMethod" name="method"><option value="BANK">بنك</option><option value="CASH">نقدي / صندوق</option></select></div><div id="payBankField" class="field"><label>الحساب البنكي</label><select name="bank">${options(S.banks.filter(b=>b.currency===i.currency),'bank_account_id','account_name')}</select></div><div id="payCashField" class="field hidden"><label>حساب الصندوق</label><select name="cash">${accountOptions(a=>a.account_class==='ASSET')}</select></div><div class="field"><label>المبلغ</label><input name="amount" type="number" step="0.01" min="0.01" max="${remaining}" value="${remaining}" required></div><div class="field"><label>العملة / السعر</label><input value="${i.currency} @ ${fmt(i.exchange_rate,6)}" disabled></div><div class="field"><label>مرجع السداد</label><input name="ref"></div><div class="field full"><label>البيان</label><input name="desc" value="${type==='SALES'?'تحصيل':'سداد'} فاتورة ${esc(i.invoice_no)}"></div></div>`,f=>{const m=f.get('method');return api(`/api/invoices/${invoiceId}/payments`,{method:'POST',body:JSON.stringify({payment_no:f.get('no'),payment_date:f.get('date'),payment_method:m,settlement_account_id:m==='CASH'?(f.get('cash')||null):null,bank_account_id:m==='BANK'?(f.get('bank')||null):null,amount:Number(f.get('amount')),exchange_rate:Number(i.exchange_rate),reference_no:f.get('ref')||null,description:f.get('desc')||null})})});setTimeout(()=>{function toggle(){const m=$('payMethod').value;$('payBankField').classList.toggle('hidden',m!=='BANK');$('payCashField').classList.toggle('hidden',m!=='CASH')}$('payMethod').onchange=toggle;toggle()},0)}

function newCash(){requireCompany();if(!S.banks.length)throw Error('أنشئ حساباً بنكياً أولاً');openModal('سند قبض / صرف',`<div class="form-grid"><div class="field"><label>النوع</label><select name="type"><option value="RECEIPT">سند قبض</option><option value="PAYMENT">سند صرف</option></select></div><div class="field"><label>الرقم</label><input name="no" required></div><div class="field"><label>التاريخ</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>الحساب البنكي</label><select name="bank" required>${options(S.banks,'bank_account_id','account_name')}</select></div><div class="field"><label>الطرف اختياري</label><select name="party">${options(S.parties,'party_id','party_name')}</select></div><div class="field"><label>الحساب المقابل</label><select name="offset">${accountOptions()}</select></div><div class="field"><label>المبلغ بعملة البنك</label><input name="amount" type="number" step="0.01" required></div><div class="field"><label>سعر الصرف اختياري</label><input name="rate" type="number" step="0.000001"></div><div class="field"><label>المرجع</label><input name="ref"></div><div class="field full"><label>البيان</label><input name="desc"></div></div>`,f=>api('/api/cash-transactions',{method:'POST',body:JSON.stringify({company_id:S.companyId,transaction_type:f.get('type'),transaction_no:f.get('no'),transaction_date:f.get('date'),bank_account_id:f.get('bank'),party_id:f.get('party')||null,offset_account_id:f.get('offset')||null,amount:Number(f.get('amount')),exchange_rate:f.get('rate')?Number(f.get('rate')):null,description:f.get('desc')||null,reference_no:f.get('ref')||null})}))}
function revalueBanks(){requireCompany();openModal('إعادة تقييم البنوك الأجنبية',`<div class="form-grid"><div class="field"><label>تاريخ التقييم</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>حساب أرباح فروق العملة</label><select name="gain" required>${accountOptions(a=>a.account_class==='REVENUE')}</select></div><div class="field"><label>حساب خسائر فروق العملة</label><select name="loss" required>${accountOptions(a=>a.account_class==='EXPENSE')}</select></div><div class="field full"><p class="muted">يستخدم النظام آخر سعر CLOSING مسجل لكل عملة حتى تاريخ التقييم.</p></div></div>`,async f=>{const preview=await api(`/api/bank-revaluation-preview?company_id=${S.companyId}&revaluation_date=${f.get('date')}`);if(!preview.length)throw Error('لا توجد حسابات بنكية أجنبية لإعادة التقييم');const net=preview.reduce((s,x)=>s+Number(x.difference_amount),0);if(!confirm(`صافي فرق التقييم ${fmt(net)} EGP. هل تريد إنشاء القيود؟`))return {message:'تم إلغاء العملية'};return api('/api/bank-revaluations',{method:'POST',body:JSON.stringify({company_id:S.companyId,revaluation_date:f.get('date'),gain_account_id:f.get('gain'),loss_account_id:f.get('loss')})})})}
function newAssetCat(){requireCompany();openModal('فئة أصل جديدة',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" required></div><div class="field"><label>اسم الفئة</label><input name="name" required></div><div class="field"><label>حساب الأصل</label><select name="asset" required>${accountOptions(a=>a.account_class==='ASSET')}</select></div><div class="field"><label>مجمع الإهلاك</label><select name="accum" required>${accountOptions(a=>a.account_class==='ASSET')}</select></div><div class="field"><label>مصروف الإهلاك</label><select name="expense" required>${accountOptions(a=>a.account_class==='EXPENSE')}</select></div><div class="field"><label>العمر بالأشهر</label><input name="life" type="number" value="60" required></div></div>`,f=>api('/api/asset-categories',{method:'POST',body:JSON.stringify({company_id:S.companyId,category_code:f.get('code'),category_name:f.get('name'),asset_account_id:f.get('asset'),accumulated_depreciation_account_id:f.get('accum'),depreciation_expense_account_id:f.get('expense'),useful_life_months:Number(f.get('life'))})}))}
function newAsset(){requireCompany();if(!S.assetCategories.length)throw Error('أنشئ فئة أصل أولاً');openModal('إضافة أصل ثابت',`<div class="form-grid"><div class="field"><label>الكود</label><input name="code" required></div><div class="field"><label>اسم الأصل</label><input name="name" required></div><div class="field"><label>الفئة</label><select name="cat" required>${options(S.assetCategories,'asset_category_id','category_name')}</select></div><div class="field"><label>تاريخ الشراء</label><input name="acq" type="date" value="${today()}" required></div><div class="field"><label>تاريخ التشغيل</label><input name="service" type="date" value="${today()}" required></div><div class="field"><label>التكلفة</label><input name="cost" type="number" step="0.01" required></div><div class="field"><label>القيمة التخريدية</label><input name="res" type="number" step="0.01" value="0"></div><div class="field"><label>الموقع</label><input name="loc"></div></div>`,f=>api('/api/assets',{method:'POST',body:JSON.stringify({company_id:S.companyId,asset_code:f.get('code'),asset_name:f.get('name'),asset_category_id:f.get('cat'),acquisition_date:f.get('acq'),placed_in_service_date:f.get('service'),acquisition_cost:Number(f.get('cost')),residual_value:Number(f.get('res')||0),location:f.get('loc')||null})}))}
async function runDep(){requireCompany();const d=prompt('تاريخ الإهلاك YYYY-MM-DD',today());if(!d)return;const p=await api(`/api/assets/depreciation-preview?company_id=${S.companyId}&depreciation_date=${d}`);if(!p.length)return toast('لا توجد أصول مستحقة للإهلاك');const total=p.reduce((s,x)=>s+Number(x.amount),0);if(confirm(`سيتم إهلاك ${p.length} أصل بقيمة ${fmt(total)}. متابعة؟`)){const r=await api('/api/assets/run-depreciation',{method:'POST',body:JSON.stringify({company_id:S.companyId,depreciation_date:d})});toast(`تم ترحيل الإهلاك: ${fmt(r.total_amount)}`);loadAssets()}}
const userPermissions=['ACCOUNT_MANAGE','CURRENCY_MANAGE','VOUCHER_CREATE','VOUCHER_EDIT','VOUCHER_DELETE','VOUCHER_POST','VOUCHER_REVERSE','VOUCHER_UNPOST_TEST','COMPANY_RESET','OPENING_BALANCE_CREATE','REPORT_VIEW','PARTY_MANAGE','BANK_MANAGE','ASSET_MANAGE','USER_MANAGE'];
function userFormHtml(u=null){const checked=new Set(u?.permissions||[]);return `<div class="form-grid"><div class="field"><label>الاسم</label><input name="name" value="${esc(u?.full_name||'')}" required></div><div class="field"><label>البريد</label><input name="email" type="email" value="${esc(u?.email||'')}" required></div><div class="field"><label>${u?'كلمة مرور جديدة (اختياري)':'كلمة المرور المؤقتة'}</label><input name="password" type="password" minlength="12" ${u?'':'required'}></div><div class="field"><label>الدور</label><select name="role"><option value="FINANCE_MANAGER">مدير مالي</option><option value="ACCOUNTANT">محاسب</option><option value="REVIEWER">مراجع/مرحل</option><option value="VIEWER">مشاهدة فقط</option>${u?.is_group_admin?'<option value="GROUP_ADMIN">مدير المجموعة</option>':''}</select></div><div class="field"><label>الشركة</label><select name="company">${companyOptions()}</select></div><div class="field"><label>الحالة</label><select name="active"><option value="true">نشط</option><option value="false">موقوف</option></select></div><div class="field full"><label>صلاحيات إضافية</label><div class="check-row">${userPermissions.map(p=>`<label><input type="checkbox" name="perm" value="${p}" ${checked.has(p)?'checked':''}>${p}</label>`).join('')}</div></div></div>`}
function newUser(){openModal('مستخدم جديد',userFormHtml(),f=>api('/api/users',{method:'POST',body:JSON.stringify({full_name:f.get('name'),email:f.get('email'),password:f.get('password'),role_code:f.get('role'),company_id:f.get('company')||null,permissions:f.getAll('perm')})}))}
function editUser(id){const u=S.users.find(x=>x.user_id===id);if(!u)return;openModal('تعديل المستخدم والصلاحيات',userFormHtml(u),f=>{const body={full_name:f.get('name'),email:f.get('email'),role_code:f.get('role'),company_id:u.is_group_admin?null:(f.get('company')||u.company_id),permissions:f.getAll('perm'),is_active:f.get('active')==='true'};if(f.get('password'))body.password=f.get('password');return api(`/api/users/${id}`,{method:'PATCH',body:JSON.stringify(body)})});setTimeout(()=>{const q=n=>document.querySelector(`#modalForm [name=${n}]`);q('role').value=u.is_group_admin?'GROUP_ADMIN':u.role_code;q('company').value=u.company_id||'';q('active').value=u.is_active?'true':'false'},0)}
async function deleteUser(id){if(!confirm('سيتم حذف المستخدم من الاستخدام مع الاحتفاظ بسجل التدقيق. متابعة؟'))return;try{const r=await api(`/api/users/${id}`,{method:'DELETE'});toast(r.message);loadUsers()}catch(e){toast(e.message,true)}}

async function runReport(){requireCompany();const type=$('reportType').value,from=$('reportFrom').value,to=$('reportTo').value;let d,title='';$('reportSummary').innerHTML='';if(type==='tb'){title=`ميزان المراجعة من ${from} إلى ${to}`;d=await api(`/api/trial-balance?company_id=${S.companyId}&date_from=${from}&as_of_date=${to}`);$('reportHead').innerHTML='<tr><th>الكود</th><th>الحساب</th><th>افتتاحي مدين</th><th>افتتاحي دائن</th><th>حركة مدين</th><th>حركة دائن</th><th>ختامي مدين</th><th>ختامي دائن</th></tr>';$('reportBody').innerHTML=d.map(r=>`<tr><td>${r.account_code}</td><td>${esc(r.account_name)}</td><td class="money">${fmt(r.opening_debit)}</td><td class="money">${fmt(r.opening_credit)}</td><td class="money">${fmt(r.period_debit)}</td><td class="money">${fmt(r.period_credit)}</td><td class="money"><b>${fmt(r.closing_debit)}</b></td><td class="money"><b>${fmt(r.closing_credit)}</b></td></tr>`).join('');const cd=d.reduce((x,r)=>x+Number(r.closing_debit||0),0),cc=d.reduce((x,r)=>x+Number(r.closing_credit||0),0);$('reportSummary').innerHTML=`<div class="chip">إجمالي الختامي المدين <b>${fmt(cd)}</b></div><div class="chip">إجمالي الختامي الدائن <b>${fmt(cc)}</b></div><div class="chip">الفرق <b>${fmt(cd-cc)}</b></div>`}else if(type==='ledger'){const a=$('reportAccount').value;if(!a)throw Error('اختر الحساب');title=`دفتر الأستاذ من ${from} إلى ${to}`;d=await api(`/api/general-ledger?company_id=${S.companyId}&account_id=${a}&date_from=${from}&date_to=${to}`);$('reportHead').innerHTML='<tr><th>التاريخ</th><th>القيد</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr>';$('reportBody').innerHTML=d.map(r=>`<tr><td>${r.posting_date}</td><td>${r.voucher_no}</td><td>${esc(r.entry_description||r.voucher_description||'')}</td><td class="money">${fmt(r.debit_amount)}</td><td class="money">${fmt(r.credit_amount)}</td><td class="money">${fmt(r.running_balance)}</td></tr>`).join('')}else if(type==='journal'){const a=$('reportAccount').value,status=$('reportVoucherStatus').value;title=`سجل القيود من ${from} إلى ${to}`;const q=new URLSearchParams({company_id:S.companyId,date_from:from,date_to:to,voucher_status:status});if(a)q.set('account_id',a);d=await api(`/api/journal-register?${q}`);$('reportHead').innerHTML='<tr><th>التاريخ</th><th>رقم القيد</th><th>الحالة</th><th>الحساب</th><th>البيان</th><th>مدين</th><th>دائن</th><th>المستخدم</th></tr>';$('reportBody').innerHTML=d.map(r=>`<tr><td>${r.posting_date}</td><td>${esc(r.voucher_no)}</td><td>${badge(r.status)}</td><td>${esc(r.account_code)} — ${esc(r.account_name)}</td><td>${esc(r.entry_description||r.voucher_description||'')}</td><td class="money">${fmt(r.debit_amount)}</td><td class="money">${fmt(r.credit_amount)}</td><td>${esc(r.created_by_name||'—')}</td></tr>`).join('');const debit=d.reduce((x,r)=>x+Number(r.debit_amount||0),0),credit=d.reduce((x,r)=>x+Number(r.credit_amount||0),0);$('reportSummary').innerHTML=`<div class="chip">عدد السطور <b>${d.length}</b></div><div class="chip">إجمالي المدين <b>${fmt(debit)}</b></div><div class="chip">إجمالي الدائن <b>${fmt(credit)}</b></div>`}else if(type==='income'){title=`قائمة الدخل من ${from} إلى ${to}`;d=await api(`/api/income-statement?company_id=${S.companyId}&date_from=${from}&date_to=${to}`);$('reportHead').innerHTML='<tr><th>التصنيف</th><th>الكود</th><th>الحساب</th><th>المبلغ</th></tr>';$('reportBody').innerHTML=d.rows.map(r=>`<tr><td>${r.account_class}</td><td>${r.account_code}</td><td>${esc(r.account_name)}</td><td class="money">${fmt(r.amount)}</td></tr>`).join('');$('reportSummary').innerHTML=`<div class="chip">الإيرادات <b>${fmt(d.total_revenue)}</b></div><div class="chip">المصروفات <b>${fmt(d.total_expense)}</b></div><div class="chip">صافي الربح <b>${fmt(d.net_profit)}</b></div>`}else{title=`قائمة المركز المالي وفق IFRS في ${to}`;d=await api(`/api/ifrs-statement-financial-position?company_id=${S.companyId}&as_of_date=${to}`);const sectionNames={CURRENT_ASSET:'الأصول المتداولة',NONCURRENT_ASSET:'الأصول غير المتداولة',CURRENT_LIABILITY:'الالتزامات المتداولة',NONCURRENT_LIABILITY:'الالتزامات غير المتداولة',EQUITY:'حقوق الملكية'};$('reportHead').innerHTML=`<tr><th>القسم</th><th>البند</th><th>${d.as_of_date}</th><th>مقارن ${d.comparative_date}</th></tr>`;$('reportBody').innerHTML=d.rows.map(r=>`<tr><td>${esc(sectionNames[r.section]||r.section)}</td><td>${esc(r.line_name)}</td><td class="money">${fmt(r.current_amount)}</td><td class="money">${fmt(r.comparative_amount)}</td></tr>`).join('');$('reportSummary').innerHTML=`<div class="chip">المعيار <b>${esc(d.standard)}</b></div><div class="chip">إجمالي الأصول <b>${fmt(d.totals.total_assets)}</b></div><div class="chip">إجمالي الالتزامات <b>${fmt(d.totals.total_liabilities)}</b></div><div class="chip">حقوق الملكية <b>${fmt(d.totals.equity)}</b></div><div class="chip">الفرق <b>${fmt(d.totals.difference)}</b></div>`}S.lastReportTitle=title;S.lastReportHtml=`<div class="report-period">الفترة: ${from||'البداية'} إلى ${to}</div>`+$('reportPrintArea').innerHTML}
function printWindow(title,content){const company=S.companies.find(c=>c.company_id===S.companyId);const w=window.open('','_blank','width=1100,height=800');if(!w)throw Error('اسمح للنوافذ المنبثقة لعرض معاينة الطباعة');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Tahoma,Arial;padding:25px;color:#111}h1,h2,p{margin:5px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:12px;margin-bottom:18px}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #555;padding:8px;text-align:right}.money{text-align:left;font-family:Consolas}.sign{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:60px;text-align:center}@media print{button{display:none}@page{size:A4;margin:12mm}}</style></head><body><button onclick="window.print()">طباعة / حفظ PDF</button><div class="head"><div><h2>${esc(S.me?.group_name||'Holding ERP')}</h2><p>${esc(company?.company_name||'المجموعة')}</p></div><div><h1>${esc(title)}</h1><p>تاريخ الطباعة: ${new Date().toLocaleString('ar-EG')}</p></div></div>${content}<div class="sign"><div>إعداد<br><br>................</div><div>مراجعة<br><br>................</div><div>اعتماد<br><br>................</div></div></body></html>`);w.document.close();w.focus()}
async function printVoucher(id){const v=await api(`/api/vouchers/${id}`);const rows=v.entries.map(e=>`<tr><td>${e.line_no}</td><td>${esc(e.local_account_code)} — ${esc(e.local_account_name)}</td><td>${esc(e.entry_description||'')}</td><td class="money">${fmt(e.debit_amount)}</td><td class="money">${fmt(e.credit_amount)}</td></tr>`).join('');printWindow(`قيد يومية ${v.voucher_no}`,`<p>التاريخ: ${v.posting_date} | الحالة: ${v.status} | النوع: ${v.voucher_type}</p><p>البيان: ${esc(v.description||'')}</p><table><thead><tr><th>#</th><th>الحساب</th><th>البيان</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${rows}</tbody></table>`)}
async function printInvoice(id){const i=await api(`/api/invoices/${id}`);const rows=i.lines.map(l=>`<tr><td>${l.line_no}</td><td>${esc(l.description)}</td><td class="money">${fmt(l.quantity)}</td><td class="money">${fmt(l.unit_price)}</td><td class="money">${fmt(l.net_amount)}</td><td class="money">${fmt(l.tax_amount)}</td><td class="money">${fmt(l.total_amount)}</td></tr>`).join('');const payments=(i.payments||[]).map(p=>`<tr><td>${p.payment_date}</td><td>${esc(p.payment_no)}</td><td>${paymentLabel(p.payment_method)}</td><td>${esc(p.bank_name||p.local_account_name||'')}</td><td class="money">${fmt(p.amount)} ${p.currency}</td></tr>`).join('');printWindow(`${i.invoice_type==='SALES'?'فاتورة مبيعات':'فاتورة مشتريات'} ${i.invoice_no}`,`<div><p>الطرف: <b>${esc(i.party_name)}</b></p><p>التاريخ: ${i.invoice_date} | الاستحقاق: ${i.due_date}</p><p>طريقة السداد: <b>${paymentLabel(i.payment_method)}</b> | العملة: ${i.currency} | سعر الصرف: ${fmt(i.exchange_rate,6)}</p></div><table><thead><tr><th>#</th><th>البيان</th><th>كمية</th><th>السعر</th><th>الصافي</th><th>الضريبة</th><th>الإجمالي</th></tr></thead><tbody>${rows}</tbody></table><h3>الإجمالي: ${fmt(i.total_amount)} ${i.currency}</h3><h3>المسدّد: ${fmt(i.paid_amount)} ${i.currency} — المتبقي: ${fmt(i.outstanding_amount)} ${i.currency}</h3><h3>القيمة الدفترية: ${fmt(i.base_total_amount)} EGP</h3>${payments?`<h3>سجل السداد</h3><table><thead><tr><th>التاريخ</th><th>السند</th><th>الطريقة</th><th>الحساب</th><th>المبلغ</th></tr></thead><tbody>${payments}</tbody></table>`:''}`)}


function wire(){
$('loginForm').onsubmit=login;$('logout').onclick=()=>logout();$('menu').onclick=()=>$('side').classList.toggle('open');$('companySelect').onchange=async e=>{S.companyId=e.target.value;localStorage.erp_company=S.companyId;await loadContext();await loaders[S.page]?.()};document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$('modalClose').onclick=$('modalCancel').onclick=closeModal;$('modalBg').onclick=e=>{if(e.target===$('modalBg'))closeModal()};$('modalForm').onsubmit=async e=>{e.preventDefault();if(!S.modalSubmit)return;const f=new FormData(e.target);const btn=e.submitter||e.target.querySelector('[type=submit]');try{if(btn)btn.disabled=true;const r=await S.modalSubmit(f);closeModal();toast(r?.message||'تم الحفظ');await loadContext();await loaders[S.page]?.()}catch(x){toast(x.message,true)}finally{if(btn)btn.disabled=false}};
$('newCompany').onclick=newCompany;$('editGroupProfile').onclick=editGroupProfile;$('newFiscalYear').onclick=newFY;$('newGroupAccount').onclick=newGA;$('newCompanyAccount').onclick=newCA;$('applyProfessionalChart').onclick=applyProfessionalChart;$('newCurrency').onclick=newCurrency;$('newRate').onclick=newRate;$('newOpening').onclick=newOpening;$('newVoucher').onclick=()=>openVoucherEditor();document.querySelectorAll('[data-chart-tab]').forEach(b=>b.onclick=()=>{S.chartTab=b.dataset.chartTab;document.querySelectorAll('[data-chart-tab]').forEach(x=>x.classList.toggle('active',x===b));loadChart()});document.querySelectorAll('.newParty').forEach(b=>b.onclick=()=>newParty(b.dataset.type));document.querySelectorAll('.newInvoice').forEach(b=>b.onclick=()=>{try{newInvoice(b.dataset.type)}catch(e){toast(e.message,true)}});$('newBank').onclick=newBank;$('newCash').onclick=()=>{try{newCash()}catch(e){toast(e.message,true)}};$('revalueBanks').onclick=()=>revalueBanks();$('newAssetCategory').onclick=newAssetCat;$('newAsset').onclick=()=>{try{newAsset()}catch(e){toast(e.message,true)}};$('runDep').onclick=()=>runDep().catch(e=>toast(e.message,true));$('newUser').onclick=newUser;$('reloadAudit').onclick=loadAudit;$('runReport').onclick=()=>runReport().catch(e=>toast(e.message,true));$('printReport').onclick=()=>{if(!S.lastReportHtml){toast('اعرض التقرير أولاً',true);return}printWindow(S.lastReportTitle,S.lastReportHtml)};$('exportReportExcel').onclick=()=>{if(!$('reportBody').children.length){toast('اعرض التقرير أولاً',true);return}exportTablesExcel(S.lastReportTitle||'تقرير',[$('reportTable')])};$('exportPageExcel').onclick=()=>{try{exportActivePageExcel()}catch(e){toast(e.message,true)}};$('printPagePdf').onclick=()=>{try{printActivePage()}catch(e){toast(e.message,true)}};$('runConsolidated').onclick=loadConsolidated;$('printConsolidated').onclick=()=>printWindow('ميزان المراجعة المجمع',$('consolidatedPrintArea').innerHTML);$('reportType').onchange=e=>{const t=e.target.value;$('reportAccountField').classList.toggle('hidden',!['ledger','journal'].includes(t));$('reportStatusField').classList.toggle('hidden',t!=='journal')};$('reportFrom').value=`${new Date().getFullYear()}-01-01`;$('reportTo').value=today()
}
loadSystemBrand();wire();if(S.token)boot();
})();
